      "cheatSheet": [
        {
          "label": "CPU Scheduling Formulas",
          "formula": "TAT = CT − AT   |   WT = TAT − BT   |   RT = First_Run − AT",
          "note": "Always draw Gantt chart first and verify idle gaps in SJF/SRTF/RR."
        },
        {
          "label": "Peterson's Critical Section",
          "formula": "flag[i] = true; turn = j; while (flag[j] && turn == j);",
          "note": "Satisfies Mutual Exclusion, Progress, and Bounded Waiting for 2 processes."
        },
        {
          "label": "Coffman's 4 Deadlock Conditions",
          "formula": "1. Mutual Exclusion  2. Hold & Wait  3. No Preemption  4. Circular Wait",
          "note": "Banker's Algorithm checks Need[i] = Max[i] − Alloc[i] ≤ Work for safe sequence."
        },
        {
          "label": "Paging & TLB EMAT",
          "formula": "EMAT = h·(t_TLB + t_mem) + (1 − h)·(t_TLB + 2·t_mem)",
          "note": "Virtual Address = (Page # p, Offset d) → Physical = (Frame # f, Offset d)."
        },
        {
          "label": "Page Fault & Replacement",
          "formula": "FIFO (Belady's Anomaly) · Optimal (lowest faults) · LRU (stack/counter)",
          "note": "EMAT with page fault rate p: (1−p)·t_mem + p·t_fault_service."
        },
        {
          "label": "Disk Scheduling Seek Time",
          "formula": "FCFS · SSTF (shortest next) · SCAN (elevator to end) · C-SCAN (jump to 0)",
          "note": "SCAN/C-SCAN prevent starvation for outer/inner cylinder requests."
        }
      ]
