      "cheatSheet": [
        {
          "label": "DeMorgan's & Boolean Identities",
          "formula": "(A + B)' = A'·B'   |   (A·B)' = A' + B'   |   A + A'B = A + B",
          "note": "NAND and NOR are universal gates (can build NOT, AND, OR, XOR)."
        },
        {
          "label": "2's Complement Range & Arithmetic",
          "formula": "Range (n-bit): −2ⁿ⁻¹ to +(2ⁿ⁻¹ − 1) · Overflow if carry_in(MSB) ≠ carry_out(MSB)",
          "note": "2's complement = 1's complement + 1; ignore final end-around carry."
        },
        {
          "label": "BCD Adder Correction (IC 7483)",
          "formula": "If binary sum > 9 OR C_out = 1, add 0110 (6) to restore valid BCD",
          "note": "Correction logic: Y = C_out + S₃·S₂ + S₃·S₁."
        },
        {
          "label": "Flip-Flop Characteristic Eqns",
          "formula": "SR: Q⁺ = S + R'Q · JK: Q⁺ = JQ' + K'Q · D: Q⁺ = D · T: Q⁺ = T ⊕ Q",
          "note": "Master-Slave JK eliminates race-around condition when J=K=1."
        },
        {
          "label": "Mod-N Counter & Ripple Delay",
          "formula": "Flip-flops needed: ⌈log₂ N⌉   |   Max f_clk ≤ 1 / (n · t_pd) for ripple",
          "note": "Ring counter uses n FFs for Mod-n; Johnson counter uses n FFs for Mod-2n."
        },
        {
          "label": "PLA vs PAL vs PROM",
          "formula": "PROM: Fixed AND, Prog OR · PAL: Prog AND, Fixed OR · PLA: Both Programmable",
          "note": "CMOS offers ultra-low static power dissipation and high noise immunity vs TTL."
        }
      ]
